sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float method;
uniform float width;
uniform float strength;
uniform float cutoff;
uniform float softness;
layout(color) uniform half4 edgeColor;
layout(color) uniform half4 backColor;
uniform float invert;
uniform float keepOriginal;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float edgeAt(float2 p, float w) {
    float tl = luma(tex(p + float2(-w, -w)).rgb);
    float tc = luma(tex(p + float2(0.0, -w)).rgb);
    float tr = luma(tex(p + float2(w, -w)).rgb);
    float ml = luma(tex(p + float2(-w, 0.0)).rgb);
    float mr = luma(tex(p + float2(w, 0.0)).rgb);
    float bl = luma(tex(p + float2(-w, w)).rgb);
    float bc = luma(tex(p + float2(0.0, w)).rgb);
    float br = luma(tex(p + float2(w, w)).rgb);
    float gx = -tl - 2.0 * ml - bl + tr + 2.0 * mr + br;
    float gy = -tl - 2.0 * tc - tr + bl + 2.0 * bc + br;
    return length(float2(gx, gy));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float e = 0.0;
    if (method < 0.5) {
        e = edgeAt(coord, width);
    } else {
        float l = luma(c.rgb);
        e = abs(luma(tex(coord + float2(width, 0.0)).rgb) + luma(tex(coord - float2(width, 0.0)).rgb) + luma(tex(coord + float2(0.0, width)).rgb) + luma(tex(coord - float2(0.0, width)).rgb) - 4.0 * l);
    }
    float k = smoothstep(cutoff, cutoff + softness + 0.001, e * strength);
    if (invert > 0.5) k = 1.0 - k;
    float3 o = mix(float3(backColor.rgb), float3(edgeColor.rgb), k);
    o = mix(o, s, keepOriginal);
    return fin(c, float4(o * c.a, c.a), opacity);
}
